-- Turn the staged extract into the served EAO layer.
--
-- Runs inside the ingest's transaction, after validate.sql. No BEGIN or COMMIT
-- here: the ingest owns the transaction, so a file that fails anywhere leaves
-- the previous load intact.
--
-- style_category is generated by
-- services/local_layer_service/eao_categories.py and repeated here literally
-- so this file can be read and run by hand. test_eao_sql.py fails if the two
-- drift apart - change the module, then paste its output here.

-- DELETE, not TRUNCATE, as the PIP transform explains: TRUNCATE takes an
-- ACCESS EXCLUSIVE lock and holds it until commit, so every tile request
-- queues behind the insert, the simplify, the style write and the history
-- write. This layer is drawn on every open map, so that window is every map's.
-- DELETE takes ROW EXCLUSIVE, under which readers keep seeing the previous
-- load until this transaction commits. The dead rows go in the ingest's VACUUM.
DELETE FROM cache.eao_project_data;

-- Every delivered row, nothing folded: EAO's GlobalID is what says whether two
-- rows are one feature, and it distinguishes all 953 of them.
--
-- Rows EAO flags sensitive or data-restricted are loaded with the rest, and
-- deliberately: most of these projects are public except for those rows, and
-- this application is internal, where all of it is available to staff. The
-- flags are carried per row so the UI can act on them - showing a sensitivity
-- marker, and defaulting such rows off - which is its own ticket. Do not add a
-- predicate here without that decision changing: it would hide data this
-- audience is entitled to.
--
-- 127 polygons are byte-identical to another in every attribute and geometry
-- and differ only by that id. They are kept, being EAO's to merge, and reported
-- as a data question rather than collapsed here. None of them is a footprint,
-- so none stacks in the view that draws footprints only.
INSERT INTO cache.eao_project_data (
    feature_id, source_layer, style_category, is_amendment, is_footprint,
    track_id, project_name, proponent, label, comment, category, subcategory,
    component_type, amendment_number, source_of_spatial, gis_adjusted,
    gis_comment, sensitive, data_restriction, date_received, engage_id,
    from_engage, geom
)
SELECT *
FROM (
    SELECT
        btrim(s.global_id) AS feature_id,
        s.source_layer,

        -- The footprint branch is dropped for lines and points: the point
        -- class has no Footprint column, and the prototype gives line
        -- features the component colours only.
        CASE
            WHEN s.source_layer = 'poly' THEN
                CASE
                    WHEN lower(btrim(coalesce(footprint, ''))) = 'yes' THEN 'footprint'
                    WHEN lower(btrim(coalesce(subcategory, ''))) = 'amendment' THEN 'amendment'
                    WHEN lower(btrim(coalesce(component_type, ''))) LIKE 'value%' THEN 'value_component'
                    ELSE 'project_component'
                END
            ELSE
                CASE
                    WHEN lower(btrim(coalesce(subcategory, ''))) = 'amendment' THEN 'amendment'
                    WHEN lower(btrim(coalesce(component_type, ''))) LIKE 'value%' THEN 'value_component'
                    ELSE 'project_component'
                END
        END AS style_category,

        lower(btrim(coalesce(s.subcategory, ''))) = 'amendment' AS is_amendment,
        lower(btrim(coalesce(s.footprint, ''))) = 'yes'         AS is_footprint,

        btrim(s.track_id)::integer AS track_id,
        btrim(s.project_name)      AS project_name,
        nullif(btrim(coalesce(s.proponent, '')), '')         AS proponent,
        btrim(s.label)                                       AS label,
        nullif(btrim(coalesce(s.comment, '')), '')           AS comment,
        nullif(btrim(coalesce(s.category, '')), '')          AS category,
        nullif(btrim(coalesce(s.subcategory, '')), '')       AS subcategory,
        nullif(btrim(coalesce(s.component_type, '')), '')    AS component_type,
        -- 'N/A' and 'No' are two of the four ways this column says "none".
        nullif(nullif(nullif(btrim(coalesce(s.amendment_number, '')), ''), 'N/A'), 'No')
            AS amendment_number,
        nullif(btrim(coalesce(s.source_of_spatial, '')), '') AS source_of_spatial,

        CASE lower(btrim(coalesce(s.gis_adjusted, '')))
            WHEN 'yes' THEN true WHEN 'no' THEN false ELSE NULL END AS gis_adjusted,
        nullif(btrim(coalesce(s.gis_comment, '')), '') AS gis_comment,
        CASE lower(btrim(coalesce(s.sensitive, '')))
            WHEN 'yes' THEN true WHEN 'no' THEN false ELSE NULL END AS sensitive,
        nullif(btrim(coalesce(s.data_restriction, '')), '') AS data_restriction,

        -- Null rather than a wrong date. The first delivery carries 30 rows
        -- whose value is a length read as a 1900-system serial, and 91 dated
        -- two months into the future; both are reported to EAO. A date that
        -- cannot be read is not worth refusing the load over.
        CASE
            WHEN s.date_received IS NULL THEN NULL
            WHEN s.date_received::date < DATE '1990-01-01' THEN NULL
            WHEN s.date_received::date > (now() AT TIME ZONE 'utc')::date THEN NULL
            ELSE s.date_received::date
        END AS date_received,

        -- The delivery writes the string 'None' where there is no Engage id.
        CASE WHEN btrim(coalesce(s.engage_id, '')) ~ '^[0-9]+$'
             THEN btrim(s.engage_id)::integer END AS engage_id,
        CASE lower(btrim(coalesce(s.from_engage, '')))
            WHEN 'yes' THEN true WHEN 'no' THEN false ELSE NULL END AS from_engage,
        s.geom
    FROM cache.eao_project_data_src s
) AS derived;

-- A simplified copy for the zooms where the province is a handful of tiles.
-- 250 is metres in EPSG:3857, about 147m on the ground at 54N. Polygons and
-- lines only: there is nothing useful to simplify a point to, and the tile SQL
-- coalesces rather than switching column for that reason.
--
-- MakeValid because SimplifyPreserveTopology can emit a degenerate ring, and
-- CollectionExtract because it can leave a collection behind. Rows whose
-- geometry simplifies away entirely keep a null here and draw from geom.
UPDATE cache.eao_project_data
   SET geom_generalized = nullif(
           ST_CollectionExtract(
               ST_MakeValid(ST_SimplifyPreserveTopology(geom, 250))),
           'GEOMETRYCOLLECTION EMPTY'::geometry)
 WHERE source_layer <> 'point';

-- The staging table and ANALYZE are the ingest's, after the commit: a DROP in
-- here would roll back with a dry run, and ANALYZE does nothing useful inside
-- a transaction.
